import { describe, expect, it } from 'vitest';
import { Session } from '../src/engine/interpreter';

/*
 * read_data as native LAMMPS reads a data file (src/read_data.cpp command, header, parse_keyword and the section
 * readers, src/atom.cpp data_atoms, data_vels, data_bonds and set_mass, src/atom_vec.cpp data_atom and the styles'
 * data_atom_post at b332f28): the keywords, the header lines recognized by their pattern (a line that is none ends the
 * header and must name a section), the line after each section keyword skipped (none: the end of the file), each
 * section reading its count of lines with blank and comment lines among them, and the messages of each check.
 * Measured with native LAMMPS (/home/roy/.local/bin/lmp, b332f28): each row is an input and the data file d.data it
 * reads; the expected error is the first line of native's message (null when the input runs) and the values are the
 * lines print wrote that start with VAL, joined by spaces. Not compared here: the message of a missing file.
 */

const outcome = async (input: string, data: string): Promise<{ error: string | null; vals: string }> => {
  const vals: string[] = [];
  const s = new Session({
    emit: (ev: { kind: string; text?: string }) => { if (ev.kind === 'log' && ev.text?.startsWith('VAL ')) vals.push(ev.text); },
    writeFile: () => {},
  } as never);
  s.addFile('d.data', data);
  let error: string | null = null;
  // the engine's message starts with the line of the input ("line N: "), which native prints elsewhere
  try { await s.execute(input); } catch (e) { error = (e as Error).message.split('\n')[0].replace(/^line \d+: /, ''); }
  return { error, vals: vals.join(' ') };
};

