/**
 * Inputs the engine refuses where native LAMMPS reads on: [input, data file, engine message, native result]. An angle
 * whose middle atom exists but another does not is kept by native until a run looks its atoms up.
 */
const REFUSED: [string, string, string, string][] = [
  ["units lj\natom_style full\nread_data d.data\nprint \"VAL $(bonds)\"\n", "LAMMPS data file\n\n3 atoms\n2 atom types\n2 bonds\n1 bond types\n1 angles\n1 angle types\n\n0 10 xlo xhi\n0 10 ylo yhi\n0 10 zlo zhi\n\nMasses\n\n1 1.0\n2 2.0\n\nAtoms # full\n\n1 1 1 0.5 1.0 1.0 1.0\n2 1 2 -0.5 2.0 1.0 1.0\n5 1 1 0.0 3.0 1.0 1.0\n\nBonds\n\n1 1 1 2\n2 1 2 5\n\nAngles\n\n1 1 1 2 3\n", "data file: angle references atom 3, which does not exist (native LAMMPS stops at the first run for it)", "reads the file; the first run stops with \"Angle atoms 1 2 3 missing on proc 0 at step 0\""],
];

const label = (input: string): string => input.split('\n').slice(2).join(' / ');

describe('read_data as native LAMMPS', () => {
  it.each(ROWS.map(([i, d, e, v], k) => [`${k + 1}: ${label(i)}`, i, d, e, v] as const))('%s', async (_name, input, data, error, vals) => {
    const got = await outcome(input, data);
    expect(got.error).toBe(error);
    expect(got.vals).toBe(vals);
  });
});

describe('read_data inputs the engine refuses', () => {
  it.each(REFUSED.map(([i, d, e], k) => [`${k + 1}: ${label(i)}`, i, d, e] as const))('%s', async (_name, input, data, expected) => {
    expect((await outcome(input, data)).error).toBe(expected);
  });
});
